                    grid[nx][ny] = str(r + 1)
                    deque_array[r].append((nx, ny, step + 1))
        # print_grid(grid)
        curr_round += 1

    cell_count = [0] * p
    for i in range(n):
        for j in range(m):
            if '1' <= grid[i][j] <= '9':
                x = int(grid[i][j])
                cell_count[x - 1] += 1
    for r in range(p):
        print(cell_count[r], end=' ')
    print()


