    #     elif S[i-1] == 'C':
    #         count_c[i] += 1
    #     elif S[i-1] == 'T':
    #         count_t[i] += 1

    # i文字目からj文字目までの（Aの数）=（Tの数）and（Cの数）=（Gの数）となる (i,j)
    n = 0
    for i in range(-1, N-1):
        count_a = 0
        count_g = 0
        count_c = 0
        count_t = 0
        for j in range(i+1, N):
            if S[j] == 'A':
                count_a += 1
            elif S[j] == 'G':
                count_g += 1
            elif S[j] == 'C':
                count_c += 1
            elif S[j] == 'T':
                count_t += 1
            if (count_a == count_t) and (count_c == count_g):
                n += 1

    return n


