    if '.' not in x:
        return int(x)
    i = len(x) - 1
    cnt = 0
    while x[i] != '.':
        i -= 1
        cnt += 1
    if cnt == 2:
        x1 = int(remd(x[:i]))
        x2 = int(x[i + 1:])
        return x1 + x2 / 100
    else:
